sp_widget.client_script:
api.controller = function($window) {

    var c =
        this;


    /* ======================================================
       SCORE RING
    ====================================================== */

    var circumference =
        465;


    var score =
        0;


    if (
        c.data &&
        c.data.match &&
        c.data.match.overallScore !== null &&
        c.data.match.overallScore !== undefined &&
        c.data.match.overallScore !== ''
    ) {

        score =
            parseFloat(
                c.data.match.overallScore
            ) || 0;
    }


    /* ======================================================
       KEEP SCORE BETWEEN 0 AND 100
    ====================================================== */

    score =
        Math.max(
            0,
            Math.min(
                100,
                score
            )
        );


    c.ringOffset =
        circumference -
        (
            circumference *
            score /
            100
        );


    /* ======================================================
       CLAIM STATE HELPERS
    ====================================================== */

    c.hasExistingClaim =
        function() {

            return (
                c.data &&
                c.data.hasExistingClaim === true
            );

        };


    c.canStartClaim =
        function() {

            return (
                c.data &&
                c.data.ownsLost === true &&
                c.data.hasExistingClaim !== true &&
                c.data.canClaim === true
            );

        };


    c.isClaimRejected =
        function() {

            return (
                c.data &&
                c.data.hasExistingClaim === true &&
                c.data.claimStatusValue === 'rejected'
            );

        };


    c.isClaimWithdrawn =
        function() {

            return (
                c.data &&
                c.data.hasExistingClaim === true &&
                c.data.claimStatusValue === 'withdrawn'
            );

        };


    /* ======================================================
       NOT MY ITEM
    ====================================================== */

    c.notMineProcessing =
        false;


    c.notMineMessage =
        '';


    c.notMineError =
        false;


    c.markNotMine =
        function() {

            if (
                c.notMineProcessing ||
                !c.data ||
                !c.data.match ||
                c.data.canDismissMatch !== true
            ) {

                return;

            }


            var confirmed =
                $window.confirm(
                    'Not your item? This match will be dismissed and CampusMatch will continue looking for another possible match.'
                );


            if (
                !confirmed
            ) {

                return;

            }


            c.notMineProcessing =
                true;


            c.notMineMessage =
                '';


            c.notMineError =
                false;


            c.server.get({

                action:
                    'markNotMine',

                match_id:
                    c.data.match.sys_id

            }).then(

                function(response) {

                    c.notMineProcessing =
                        false;


                    if (
                        !response ||
                        !response.data ||
                        response.data.success !== true
                    ) {

                        c.notMineError =
                            true;


                        c.notMineMessage =
                            response &&
                            response.data &&
                            response.data.message
                                ?
                                response.data.message
                                :
                                'This match could not be dismissed.';


                        return;

                    }


                    c.notMineError =
                        false;


                    c.notMineMessage =
                        response.data.message ||
                        'This match has been dismissed.';


                    $window.setTimeout(
                        function() {

                            $window.location.reload();

                        },
                        500
                    );

                },

                function() {

                    c.notMineProcessing =
                        false;


                    c.notMineError =
                        true;


                    c.notMineMessage =
                        'This match could not be dismissed. Please try again.';

                }

            );

        };

};

sp_widget.css:
/* ==========================================================
   CAMPUSMATCH — MATCH DETAILS
   COMPLETE WIDGET CSS
   WEBSITE + NOW MOBILE APP
   FULL-BLEED SAFE VERSION
========================================================== */


/* ==========================================================
   PAGE
========================================================== */

.cm-match-page {
  position: relative;
  display: block;

  width: 100vw !important;
  max-width: 100vw !important;

  margin-left: calc(50% - 50vw) !important;
  margin-right: calc(50% - 50vw) !important;

  margin-top: 0 !important;
  margin-bottom: 0 !important;

  min-height: 100vh;
  min-height: 100svh;

  box-sizing: border-box !important;

  padding: 38px 20px 80px;

  background: linear-gradient(
    180deg,
    #fbf9f3 0%,
    #f4f8f5 100%
  ) !important;

  box-shadow:
    0 -60px 0 #fbf9f3,
    0 60px 0 #f4f8f5;

  color: #173438;

  font-family:
    "Segoe UI",
    Arial,
    sans-serif;

  overflow-x: hidden;
}


.cm-match-page,
.cm-match-page *,
.cm-match-page *::before,
.cm-match-page *::after {
  box-sizing: border-box;
}


.cm-match-container {
  position: relative;

  width: 100%;
  max-width: 1000px;

  margin: 0 auto;
}


/* ==========================================================
   IMPORTANT SVG SAFETY
   Prevents giant icons
========================================================== */

.cm-match-page svg {
  display: block;
  max-width: 100%;
}


.cm-comparison-icon svg,
.cm-title-icon svg,
.cm-hidden-detail-note svg,
.cm-privacy-icon svg {
  width: 20px !important;
  height: 20px !important;

  min-width: 20px;
  min-height: 20px;
}


.cm-score-ring > svg {
  position: absolute;

  top: 0;
  left: 0;

  width: 180px !important;
  height: 180px !important;

  max-width: 180px !important;
  max-height: 180px !important;
}


/* ==========================================================
   BACK LINK
========================================================== */

.cm-back-link {
  display: inline-flex;
  align-items: center;

  margin-bottom: 28px;

  color: #176957 !important;

  font-size: 13px;
  font-weight: 600;

  text-decoration: none !important;

  transition: opacity 0.2s ease;
}


.cm-back-link:hover {
  color: #104e45 !important;
  text-decoration: none !important;

  opacity: 0.8;
}


/* ==========================================================
   HERO
========================================================== */

.cm-match-hero {
  width: 100%;

  margin-bottom: 36px;

  text-align: center;
}


.cm-match-level {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  padding: 8px 17px;

  margin-bottom: 16px;

  border-radius: 999px;

  font-size: 12px;
  font-weight: 700;

  line-height: 1;
}


.cm-match-level.strong {
  background: #e3f5eb;
  color: #168c70;
}


.cm-match-level.potential {
  background: #fff3d9;
  color: #8d6d1d;
}


.cm-match-level.low {
  background: #edf2ef;
  color: #68797c;
}


.cm-match-hero h1 {
  margin: 0 0 10px;

  color: #104e45;

  font-size: 38px;
  font-weight: 700;

  line-height: 1.2;

  letter-spacing: -1px;
}


.cm-match-hero > p {
  width: 100%;
  max-width: 610px;

  margin: 0 auto 28px;

  color: #667b7d;

  font-size: 14px;
  line-height: 1.6;
}


/* ==========================================================
   SCORE RING
========================================================== */

.cm-score-ring {
  position: relative;

  width: 180px !important;
  height: 180px !important;

  min-width: 180px;
  min-height: 180px;

  max-width: 180px;
  max-height: 180px;

  margin: 0 auto 12px;

  overflow: hidden;
}


.cm-score-ring svg {
  transform: rotate(-90deg);
}


.cm-ring-background,
.cm-ring-progress {
  fill: none !important;

  stroke-width: 13px;
}


.cm-ring-background {
  stroke: #e3ebe7 !important;
}


.cm-ring-progress {
  stroke: #249d78 !important;

  stroke-linecap: round;

  transition:
    stroke-dashoffset 0.8s ease;
}


.cm-score-content {
  position: absolute;

  top: 0;
  left: 0;

  width: 180px;
  height: 180px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  z-index: 2;
}


.cm-score-content strong {
  display: block;

  color: #104e45;

  font-size: 38px;
  font-weight: 700;

  line-height: 1;
}


.cm-score-content span {
  display: block;

  margin-top: 6px;

  color: #718285;

  font-size: 11px;
  font-weight: 600;
}


.cm-score-caption {
  display: inline-block;

  color: #168c70;

  font-size: 12px;
  font-weight: 700;
}


/* ==========================================================
   LOST / FOUND COMPARISON
========================================================== */

.cm-comparison {
  width: 100%;

  display: grid;

  grid-template-columns:
    minmax(0, 1fr)
    70px
    minmax(0, 1fr);

  align-items: center;

  gap: 16px;

  margin-bottom: 28px;
}


.cm-comparison-card {
  width: 100%;
  min-width: 0;

  padding: 24px;

  border: 1px solid #d5e0db;
  border-radius: 20px;

  background: #ffffff;

  box-shadow:
    0 5px 18px rgba(16, 78, 69, 0.05);
}


.cm-found-card {
  border-color: #bbd9cc;
}


.cm-comparison-top {
  display: flex;
  align-items: center;

  gap: 13px;

  margin-bottom: 20px;
}


.cm-comparison-icon {
  width: 48px !important;
  height: 48px !important;

  min-width: 48px;
  min-height: 48px;

  max-width: 48px;
  max-height: 48px;

  flex: 0 0 48px;

  display: flex;
  align-items: center;
  justify-content: center;

  overflow: hidden;

  border-radius: 14px;
}


.cm-lost-icon {
  background: #fbeae7;
  color: #a95840;
}


.cm-found-icon {
  background: #eaf4ec;
  color: #15564b;
}


.cm-small-label {
  display: block;

  margin-bottom: 4px;

  color: #7a898d;

  font-size: 10px;
  font-weight: 700;

  line-height: 1.2;

  text-transform: uppercase;

  letter-spacing: 0.5px;
}


.cm-comparison-top h3 {
  margin: 0;

  color: #104e45;

  font-size: 16px;
  font-weight: 700;

  line-height: 1.35;
}


/* ==========================================================
   REPORT FACTS
========================================================== */

.cm-report-facts {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 9px;
}


.cm-report-facts > div {
  min-width: 0;

  padding: 11px;

  border-radius: 11px;

  background: #f5f8f5;
}


.cm-report-facts span {
  display: block;

  margin-bottom: 4px;

  color: #819093;

  font-size: 9px;
  font-weight: 500;
}


.cm-report-facts strong {
  display: block;

  overflow: hidden;

  color: #173438;

  font-size: 11px;
  font-weight: 700;

  line-height: 1.4;

  text-overflow: ellipsis;
}


/* ==========================================================
   CONNECTOR
========================================================== */

.cm-match-connector {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  gap: 6px;

  color: #249d78;
}


.cm-match-connector > div {
  width: 44px;
  height: 44px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: #eaf4ec;

  color: #168c70;

  font-size: 18px;
  font-weight: 700;
}


.cm-match-connector > span {
  color: #738487;

  font-size: 9px;
  font-weight: 700;
}


/* ==========================================================
   HIDDEN DETAIL NOTE
========================================================== */

.cm-hidden-detail-note {
  display: flex;
  align-items: flex-start;

  gap: 8px;

  margin-top: 14px;
  padding: 11px 12px;

  border-radius: 11px;

  background: #edf5e9;

  color: #637779;

  font-size: 10px;
  line-height: 1.5;
}


.cm-hidden-detail-note svg {
  flex: 0 0 16px;

  width: 16px !important;
  height: 16px !important;

  min-width: 16px;
  min-height: 16px;

  margin-top: 1px;

  color: #15564b;
}


/* ==========================================================
   COMMON WHITE CARDS
========================================================== */

.cm-breakdown-card,
.cm-why-section {
  width: 100%;

  padding: 27px;

  margin-bottom: 23px;

  border: 1px solid #d5e0db;
  border-radius: 20px;

  background: #ffffff;

  box-shadow:
    0 5px 18px rgba(16, 78, 69, 0.05);
}


/* ==========================================================
   SECTION TITLES
========================================================== */

.cm-section-title {
  display: flex;
  align-items: flex-start;

  gap: 12px;

  margin-bottom: 24px;
}


.cm-title-icon {
  width: 40px !important;
  height: 40px !important;

  min-width: 40px;
  min-height: 40px;

  max-width: 40px;
  max-height: 40px;

  flex: 0 0 40px;

  display: flex;
  align-items: center;
  justify-content: center;

  overflow: hidden;

  border-radius: 12px;

  background: #edf5e9;

  color: #15564b;
}


.cm-title-icon svg {
  width: 19px !important;
  height: 19px !important;

  min-width: 19px;
  min-height: 19px;
}


.cm-section-title h2 {
  margin: 0 0 4px;

  color: #104e45;

  font-size: 19px;
  font-weight: 700;

  line-height: 1.3;
}


.cm-section-title p {
  margin: 0;

  color: #7b8b8d;

  font-size: 11px;
  line-height: 1.5;
}


/* ==========================================================
   MATCH FACTORS
========================================================== */

.cm-factor-list {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 22px 32px;
}


.cm-factor {
  min-width: 0;
}


.cm-factor-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  gap: 15px;

  margin-bottom: 8px;
}


.cm-factor-heading > div {
  min-width: 0;

  display: flex;
  flex-direction: column;
}


.cm-factor-heading strong {
  color: #173438;

  font-size: 12px;
  font-weight: 700;

  line-height: 1.4;
}


.cm-factor-heading span {
  margin-top: 2px;

  color: #899799;

  font-size: 9px;
}


.cm-factor-heading b {
  flex-shrink: 0;

  color: #15564b;

  font-size: 12px;
  font-weight: 700;
}


.cm-factor-track {
  width: 100%;
  height: 8px;

  overflow: hidden;

  border-radius: 999px;

  background: #eaf0ed;
}


.cm-factor-fill {
  height: 8px;

  min-width: 0;

  border-radius: 999px;

  background: linear-gradient(
    90deg,
    #168c70,
    #2ca77f
  );

  transition: width 0.5s ease;
}


/* ==========================================================
   WHY THIS MATCHED
========================================================== */

.cm-reasons {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 11px;
}


.cm-reason {
  min-height: 44px;

  padding: 11px 13px;

  display: flex;
  align-items: center;

  gap: 9px;

  border-radius: 12px;

  background: #edf5e9;

  color: #15564b;

  font-size: 11px;
  font-weight: 700;

  line-height: 1.4;
}


.cm-reason > span {
  width: 20px;
  height: 20px;

  min-width: 20px;
  min-height: 20px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex: 0 0 20px;

  border-radius: 50%;

  background: #249d78;

  color: #ffffff;

  font-size: 10px;
  font-weight: 700;
}


.cm-no-reasons {
  color: #718185;

  font-size: 12px;
  line-height: 1.5;
}


/* ==========================================================
   PRIVACY CARD
========================================================== */

.cm-privacy-card {
  width: 100%;

  display: flex;
  align-items: flex-start;

  gap: 13px;

  padding: 18px 20px;

  margin-bottom: 23px;

  border: 1px solid #dce9e1;
  border-radius: 17px;

  background: #edf5e9;
}


.cm-privacy-icon {
  width: 40px !important;
  height: 40px !important;

  min-width: 40px;
  min-height: 40px;

  max-width: 40px;
  max-height: 40px;

  flex: 0 0 40px;

  display: flex;
  align-items: center;
  justify-content: center;

  overflow: hidden;

  border-radius: 12px;

  background: #ffffff;

  color: #15564b;
}


.cm-privacy-icon svg {
  width: 19px !important;
  height: 19px !important;

  min-width: 19px;
  min-height: 19px;
}


.cm-privacy-card strong {
  display: block;

  margin-bottom: 4px;

  color: #104e45;

  font-size: 12px;
  font-weight: 700;
}


.cm-privacy-card p {
  margin: 0;

  color: #607577;

  font-size: 11px;
  line-height: 1.55;
}


/* ==========================================================
   CLAIM / VERIFICATION CARD
========================================================== */

.cm-claim-card {
  width: 100%;

  padding: 38px 34px;

  overflow: hidden;

  border-radius: 23px;

  background: linear-gradient(
    135deg,
    #104e45 0%,
    #176b5c 100%
  );

  color: #ffffff;

  text-align: center;

  box-shadow:
    0 14px 32px rgba(16, 78, 69, 0.16);
}


.cm-claim-eyebrow {
  display: inline-block;

  margin-bottom: 8px;

  color: #bde8d8;

  font-size: 10px;
  font-weight: 800;

  text-transform: uppercase;

  letter-spacing: 0.8px;
}


.cm-claim-card h2 {
  margin: 0 0 8px;

  color: #ffffff !important;

  font-size: 24px;
  font-weight: 700;

  line-height: 1.3;
}


.cm-claim-card p {
  width: 100%;
  max-width: 530px;

  margin: 0 auto 21px;

  color: rgba(255, 255, 255, 0.78);

  font-size: 12px;
  line-height: 1.65;
}


.cm-claim-card p strong {
  color: #ffffff;
}


/* ==========================================================
   CLAIM ACTION BUTTON
========================================================== */

.cm-claim-button {
  min-width: 220px;

  min-height: 46px;

  padding: 12px 22px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  gap: 10px;

  border: none;
  border-radius: 999px;

  background: #ffffff;

  color: #104e45 !important;

  font-size: 13px;
  font-weight: 800;

  line-height: 1;

  text-decoration: none !important;

  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}


.cm-claim-button:hover,
.cm-claim-button:focus {
  color: #104e45 !important;

  text-decoration: none !important;

  transform: translateY(-2px);

  box-shadow:
    0 8px 18px rgba(0, 0, 0, 0.15);
}


.cm-claim-button > span {
  display: inline-block;

  font-size: 18px;
  line-height: 1;
}


/* ==========================================================
   NEW — MATCH DECISION ACTIONS
========================================================== */

.cm-claim-actions {
  display: flex;

  align-items: center;
  justify-content: center;

  flex-wrap: wrap;

  gap: 12px;

  margin-top: 4px;
}


/* ==========================================================
   NEW — NOT MY ITEM BUTTON
========================================================== */

.cm-not-mine-button {
  min-width: 190px;
  min-height: 46px;

  padding: 12px 22px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  border: 1px solid rgba(255, 255, 255, 0.55);
  border-radius: 999px;

  background: rgba(255, 255, 255, 0.08);

  color: #ffffff;

  font-family:
    "Segoe UI",
    Arial,
    sans-serif;

  font-size: 13px;
  font-weight: 800;

  line-height: 1;

  cursor: pointer;

  outline: none;

  transition:
    transform 0.2s ease,
    background 0.2s ease,
    border-color 0.2s ease,
    opacity 0.2s ease;
}


.cm-not-mine-button:hover:not(:disabled),
.cm-not-mine-button:focus:not(:disabled) {
  transform: translateY(-2px);

  border-color: #ffffff;

  background: rgba(255, 255, 255, 0.16);

  color: #ffffff;
}


.cm-not-mine-button:disabled {
  opacity: 0.55;

  cursor: not-allowed;

  transform: none;
}


/* ==========================================================
   NEW — MATCH ACTION MESSAGE
========================================================== */

.cm-match-action-message {
  width: 100%;
  max-width: 520px;

  margin: 15px auto 0;
  padding: 10px 13px;

  border: 1px solid rgba(189, 232, 216, 0.32);
  border-radius: 11px;

  background: rgba(255, 255, 255, 0.1);

  color: #dff4eb;

  font-size: 10px;
  font-weight: 700;

  line-height: 1.5;
}


.cm-match-action-message.error {
  border-color: rgba(255, 205, 195, 0.4);

  background: rgba(255, 225, 218, 0.12);

  color: #ffe2da;
}


/* ==========================================================
   CLAIM SMALL TEXT
========================================================== */

.cm-claim-card small {
  width: 100%;
  max-width: 510px;

  display: block;

  margin: 15px auto 0;

  color: rgba(255, 255, 255, 0.6);

  font-size: 9px;
  line-height: 1.55;
}


/* ==========================================================
   ERROR / EMPTY STATES
========================================================== */

.cm-state-card {
  width: 100%;
  max-width: 520px;

  padding: 48px 30px;

  margin: 35px auto;

  border: 1px solid #d5e0db;
  border-radius: 21px;

  background: #ffffff;

  text-align: center;

  box-shadow:
    0 5px 18px rgba(16, 78, 69, 0.05);
}


.cm-state-icon {
  width: 58px;
  height: 58px;

  display: flex;
  align-items: center;
  justify-content: center;

  margin: 0 auto 15px;

  border-radius: 50%;

  background: #edf5e9;

  color: #15564b;

  font-size: 23px;
  font-weight: 800;
}


.cm-state-card h2 {
  margin: 0 0 8px;

  color: #104e45;

  font-size: 24px;
  font-weight: 700;
}


.cm-state-card p {
  margin: 0 0 14px;

  color: #718185;

  font-size: 13px;
}


.cm-state-card a {
  color: #168c70 !important;

  font-size: 13px;
  font-weight: 700;

  text-decoration: none !important;
}


/* ==========================================================
   SERVICE PORTAL / BOOTSTRAP PROTECTION
========================================================== */

.cm-match-page .cm-comparison-icon > svg {
  width: 22px !important;
  height: 22px !important;
}


.cm-match-page .cm-title-icon > svg {
  width: 19px !important;
  height: 19px !important;
}


.cm-match-page .cm-privacy-icon > svg {
  width: 19px !important;
  height: 19px !important;
}


.cm-match-page .cm-hidden-detail-note > svg {
  width: 16px !important;
  height: 16px !important;
}


.cm-match-page .cm-score-ring > svg {
  width: 180px !important;
  height: 180px !important;
}


.cm-match-page circle,
.cm-match-page path,
.cm-match-page rect {
  vector-effect: non-scaling-stroke;
}


/* ==========================================================
   TABLET
========================================================== */

@media screen and (max-width: 820px) {

  .cm-match-page {
    min-height: 100svh;

    padding:
      32px
      18px
      65px;

    box-shadow:
      0 -60px 0 #fbf9f3,
      0 60px 0 #f4f8f5;
  }


  .cm-match-hero h1 {
    font-size: 33px;
  }


  .cm-comparison {
    grid-template-columns: 1fr;

    gap: 15px;
  }


  .cm-match-connector {
    flex-direction: row;

    padding: 2px 0;
  }


  .cm-match-connector > div {
    width: 40px;
    height: 40px;
  }


  .cm-factor-list {
    grid-template-columns: 1fr;
  }


  .cm-reasons {
    grid-template-columns: 1fr;
  }

}


/* ==========================================================
   MOBILE
========================================================== */

@media screen and (max-width: 560px) {

  .cm-match-page {
    min-height: 100svh;

    padding:
      25px
      12px
      55px;

    box-shadow:
      0 -60px 0 #fbf9f3,
      0 60px 0 #f4f8f5;
  }


  .cm-back-link {
    margin-bottom: 22px;

    font-size: 12px;
  }


  .cm-match-hero {
    margin-bottom: 28px;
  }


  .cm-match-hero h1 {
    font-size: 28px;

    letter-spacing: -0.5px;
  }


  .cm-match-hero > p {
    margin-bottom: 23px;

    font-size: 12px;
  }


  .cm-score-ring {
    width: 160px !important;
    height: 160px !important;

    min-width: 160px;
    min-height: 160px;

    max-width: 160px;
    max-height: 160px;
  }


  .cm-score-ring > svg {
    width: 160px !important;
    height: 160px !important;

    max-width: 160px !important;
    max-height: 160px !important;
  }


  .cm-score-content {
    width: 160px;
    height: 160px;
  }


  .cm-score-content strong {
    font-size: 32px;
  }


  .cm-comparison-card {
    padding: 19px 16px;

    border-radius: 17px;
  }


  .cm-comparison-icon {
    width: 43px !important;
    height: 43px !important;

    min-width: 43px;
    min-height: 43px;

    flex-basis: 43px;
  }


  .cm-report-facts {
    grid-template-columns: 1fr;
  }


  .cm-report-facts > div {
    padding: 10px 11px;
  }


  .cm-breakdown-card,
  .cm-why-section {
    padding: 21px 17px;

    border-radius: 17px;
  }


  .cm-section-title {
    gap: 10px;

    margin-bottom: 20px;
  }


  .cm-title-icon {
    width: 38px !important;
    height: 38px !important;

    min-width: 38px;
    min-height: 38px;

    flex-basis: 38px;
  }


  .cm-section-title h2 {
    font-size: 17px;
  }


  .cm-privacy-card {
    padding: 16px;
  }


  .cm-claim-card {
    padding:
      29px
      18px;

    border-radius: 19px;
  }


  .cm-claim-card h2 {
    font-size: 21px;
  }


  /* NEW — STACK BOTH ACTIONS ON MOBILE */

  .cm-claim-actions {
    flex-direction: column;

    align-items: stretch;

    width: 100%;
  }


  .cm-claim-actions .cm-claim-button,
  .cm-not-mine-button {
    width: 100%;
    min-width: 0;
  }


  .cm-state-card {
    padding:
      38px
      20px;
  }

}


/* ==========================================================
   EXTRA SMALL MOBILE
========================================================== */

@media screen and (max-width: 390px) {

  .cm-match-page {
    padding:
      22px
      9px
      50px;
  }


  .cm-match-hero h1 {
    font-size: 25px;
  }


  .cm-match-hero > p {
    font-size: 11px;
  }


  .cm-comparison-card {
    padding:
      17px
      14px;
  }


  .cm-breakdown-card,
  .cm-why-section {
    padding:
      19px
      14px;
  }


  .cm-privacy-card {
    padding:
      14px;
  }


  .cm-claim-card {
    padding:
      26px
      15px;
  }


  .cm-state-card {
    padding:
      33px
      16px;
  }

}

sp_widget.script:
(function() {



    /* ======================================================

       TABLES

    ====================================================== */



    var ITEM_TABLE =

        'x_snc_campusmatch_campusmatch_item';



    var MATCH_TABLE =

        'x_snc_campusmatch_campusmatch_match';



    var CLAIM_TABLE =

        'x_snc_campusmatch_campusmatch_claim';





    /* ======================================================

       DEFAULT DATA

    ====================================================== */



    data.error =

        '';



    data.match =

        null;



    data.canClaim =

        false;



    data.ownsLost =

        false;



    data.ownsFound =

        false;



    data.isStaff =

        false;



    data.disambiguationRequired =

        false;



    data.staffReviewRequired =

        false;



    data.matchRejected =

        false;



    data.matchWithdrawn =

        false;



    data.claimWithdrawn =

        false;


    data.canDismissMatch =

        false;


    data.success =

        false;


    data.message =

        '';





    /* ======================================================

       EXISTING CLAIM STATE

    ====================================================== */



    data.hasExistingClaim =

        false;



    data.claimStatusValue =

        '';



    data.claimStatusDisplay =

        '';



    data.claimStatusTitle =

        '';



    data.claimStatusMessage =

        '';



    data.existingClaimUrl =

        '';





    /* ======================================================

       HELPER

    ====================================================== */



    function findField(

        gr,

        names

    ) {



        for (

            var i = 0;

            i < names.length;

            i++

        ) {



            if (

                gr.isValidField(

                    names[i]

                )

            ) {



                return names[i];

            }

        }





        return '';

    }





    function readScore(

        gr,

        field

    ) {



        if (!field) {



            return 0;

        }





        var n =

            parseFloat(

                gr.getValue(

                    field

                )

            );





        if (

            isNaN(n)

        ) {



            return 0;

        }





        return Math.round(

            n * 100

        ) / 100;

    }





    /* ======================================================

       MATCH ID

    ====================================================== */



    var matchId =

        '';


    if (

        input &&
        input.match_id

    ) {

        matchId =

            input.match_id;

    }

    else {

        matchId =

            $sp.getParameter(

                'match_id'

            );

    }





    if (!matchId) {



        data.error =

            'No Match record was provided.';



        return;

    }





    /* ======================================================

       LOAD MATCH

    ====================================================== */



    var match =

        new GlideRecord(

            MATCH_TABLE

        );





    if (

        !match.get(

            matchId

        )

    ) {



        data.error =

            'The Match record could not be found.';



        return;

    }





    /* ======================================================

       MATCH FIELD NAMES

    ====================================================== */



    var F_LOST =

        'lost_item';



    var F_FOUND =

        'found_item';



    var F_OVERALL =

        'overall_score';



    var F_LEVEL =

        'match_level';



    var F_STATUS =

        'status';





    var F_IMAGE =

        findField(

            match,

            [

                'image_similarity',

                'u_image_similarity'

            ]

        );





    var F_DESCRIPTION =

        findField(

            match,

            [

                'description_score',

                'description_similarity',

                'u_description_score'

            ]

        );





    var F_LOCATION =

        findField(

            match,

            [

                'location_score',

                'u_location_score'

            ]

        );





    var F_TIME =

        findField(

            match,

            [

                'time_score',

                'u_time_score'

            ]

        );





    var F_CATEGORY =

        findField(

            match,

            [

                'category_score',

                'u_category_score'

            ]

        );





    var F_UNIQUE =

        findField(

            match,

            [

                'unique_attribute_score',

                'u_unique_attribute_score'

            ]

        );





    /* ======================================================

       LOST + FOUND REFERENCES

    ====================================================== */



    var lostId =

        match.getValue(

            F_LOST

        );





    var foundId =

        match.getValue(

            F_FOUND

        );





    var lost =

        new GlideRecord(

            ITEM_TABLE

        );





    var found =

        new GlideRecord(

            ITEM_TABLE

        );





    if (

        !lostId ||

        !foundId ||

        !lost.get(

            lostId

        ) ||

        !found.get(

            foundId

        )

    ) {



        data.error =

            'Matched Item records could not be loaded.';



        return;

    }





    /* ======================================================

       ACCESS SECURITY

    ====================================================== */



    var access =

        new CampusMatchAccess();





    data.isStaff =

        access.isStaff();





    var userId =

        gs.getUserID();





    data.ownsLost =

        lost.getValue(

            'reporter'

        ) === userId;





    data.ownsFound =

        found.getValue(

            'reporter'

        ) === userId;





    if (

        !access.canViewMatch(

            lost,

            found

        )

    ) {



        data.error =

            'You do not have access to this Match.';



        return;

    }





    /* ======================================================

       USER MARKS MATCH AS "NOT MY ITEM"

    ====================================================== */

    if (

        input &&
        input.action ===
            'markNotMine'

    ) {


        /* ==================================================

           ONLY LOST REPORT OWNER CAN DISMISS

        ================================================== */

        if (

            !data.ownsLost

        ) {

            data.success =

                false;


            data.message =

                'Only the owner of the Lost report can dismiss this match.';


            return;

        }



        /* ==================================================

           MATCH MUST STILL BE OPEN

        ================================================== */

        var dismissStatus =

            (

                match.getValue(

                    F_STATUS

                ) || ''

            )

            .toString()

            .toLowerCase()

            .trim();


        if (

            dismissStatus ===
                'no_match' ||
            dismissStatus ===
                'rejected' ||
            dismissStatus ===
                'withdrawn' ||
            dismissStatus ===
                'resolved'

        ) {

            data.success =

                false;


            data.message =

                'This match is already closed.';


            return;

        }



        /* ==================================================

           CLAIM MUST NOT ALREADY EXIST

        ================================================== */

        var dismissClaim =

            new GlideRecord(

                CLAIM_TABLE

            );


        var dismissMatchField =

            findField(

                dismissClaim,

                [

                    'match',

                    'u_match'

                ]

            );


        var dismissClaimantField =

            findField(

                dismissClaim,

                [

                    'claimant',

                    'u_claimant',

                    'claimed_by'

                ]

            );


        if (

            !dismissMatchField ||
            !dismissClaimantField

        ) {

            data.success =

                false;


            data.message =

                'CampusMatch could not safely verify the claim state for this match.';


            return;

        }


        dismissClaim.addQuery(

            dismissMatchField,

            match.getUniqueValue()

        );


        dismissClaim.addQuery(

            dismissClaimantField,

            userId

        );


        dismissClaim.setLimit(

            1

        );


        dismissClaim.query();


        if (

            dismissClaim.next()

        ) {

            data.success =

                false;


            data.message =

                'An ownership claim already exists for this match. Use Withdraw Claim instead.';


            return;

        }



        /* ==================================================

           CLOSE THIS MATCH

        ================================================== */

        match.setValue(

            F_STATUS,

            'no_match'

        );


        if (

            match.isValidField(

                'decision_reason'

            )

        ) {

            match.setValue(

                'decision_reason',

                'user_rejected'

            );

        }


        match.update();



        /* ==================================================

           REOPEN COMPETING CANDIDATES

        ================================================== */

        var competitor =

            new GlideRecord(

                MATCH_TABLE

            );


        if (

            match.isValidField(

                'decision_reason'

            )

        ) {

            competitor.addQuery(

                F_FOUND,

                foundId

            );


            competitor.addQuery(

                'sys_id',

                '!=',

                match.getUniqueValue()

            );


            competitor.addQuery(

                F_OVERALL,

                '>=',

                65

            );


            competitor.addQuery(

                F_STATUS,

                'no_match'

            );


            competitor.addQuery(

                'decision_reason',

                'competing_candidate'

            );


            competitor.query();


            while (

                competitor.next()

            ) {

                competitor.setValue(

                    F_STATUS,

                    'active'

                );


                competitor.setValue(

                    'decision_reason',

                    ''

                );


                if (

                    competitor.isValidField(

                        'reviewed_by'

                    )

                ) {

                    competitor.setValue(

                        'reviewed_by',

                        ''

                    );

                }


                if (

                    competitor.isValidField(

                        'reviewed_on'

                    )

                ) {

                    competitor.setValue(

                        'reviewed_on',

                        ''

                    );

                }


                competitor.update();

            }

        }



        data.success =

            true;


        data.message =

            'Match dismissed. CampusMatch will continue looking for another possible match.';


        return;

    }





    /* ======================================================

       EXISTING CLAIM CHECK

       IMPORTANT:

       Once the logged-in Lost reporter has already created
       a Claim for this Match, they must NOT be allowed to
       start another Claim.

       This applies regardless of whether the old Claim is:

       - Submitted
       - Under Review
       - Approved
       - Rejected
       - Cancelled
       - Withdrawn

       ANY existing Claim for the same user + Match blocks
       "This might be mine".

    ====================================================== */



    if (

        data.ownsLost

    ) {



        var existingClaim =

            new GlideRecord(

                CLAIM_TABLE

            );





        /* ==================================================

           CLAIM FIELD NAMES

        ================================================== */



        var C_MATCH =

            findField(

                existingClaim,

                [

                    'match',

                    'u_match'

                ]

            );





        var C_CLAIMANT =

            findField(

                existingClaim,

                [

                    'claimant',

                    'u_claimant',

                    'claimed_by'

                ]

            );





        var C_STATUS =

            findField(

                existingClaim,

                [

                    'claim_status',

                    'u_claim_status',

                    'status'

                ]

            );





        /* ==================================================

           FAIL SAFELY

        ================================================== */



        if (

            !C_MATCH ||

            !C_CLAIMANT ||

            !C_STATUS

        ) {



            data.hasExistingClaim =

                true;





            data.claimStatusDisplay =

                'Claim status';





            data.claimStatusTitle =

                'Claim availability could not be verified';





            data.claimStatusMessage =

                'CampusMatch could not safely verify whether a claim already exists for this match.';





            gs.error(

                'CampusMatch Match Details: Claim fields could not be resolved. ' +

                'Match field=' +

                C_MATCH +

                ', Claimant field=' +

                C_CLAIMANT +

                ', Status field=' +

                C_STATUS

            );



        }

        else {



            /* ==============================================

               SAME MATCH

            ============================================== */



            existingClaim.addQuery(

                C_MATCH,

                match.getUniqueValue()

            );





            /* ==============================================

               SAME LOGGED-IN USER

            ============================================== */



            existingClaim.addQuery(

                C_CLAIMANT,

                userId

            );





            existingClaim.orderByDesc(

                'sys_created_on'

            );





            existingClaim.setLimit(

                1

            );





            existingClaim.query();





            if (

                existingClaim.next()

            ) {



                /* ==========================================

                   CLAIM ALREADY EXISTS

                ========================================== */



                data.hasExistingClaim =

                    true;





                data.claimStatusValue =

                    (

                        existingClaim.getValue(

                            C_STATUS

                        ) || ''

                    )

                    .toString()

                    .toLowerCase()

                    .trim();





                data.claimStatusDisplay =

                    existingClaim.getDisplayValue(

                        C_STATUS

                    ) ||

                    'Claim submitted';





                data.existingClaimUrl =

                    '?id=campusmatch_verification&match_id=' +

                    match.getUniqueValue();





                /* ==========================================

                   REJECTED

                ========================================== */



                if (

                    data.claimStatusValue ===

                        'rejected'

                ) {



                    data.claimStatusTitle =

                        'Ownership claim was rejected';





                    data.claimStatusMessage =

                        'Your ownership claim for this match was rejected. You cannot start another claim for the same match.';



                }





                /* ==========================================

                   APPROVED

                ========================================== */



                else if (

                    data.claimStatusValue ===

                        'approved'

                ) {



                    data.claimStatusTitle =

                        'Ownership claim approved';





                    data.claimStatusMessage =

                        'Your ownership claim for this match has already been approved. Continue with the existing claim and collection process.';



                }





                /* ==========================================

                   UNDER REVIEW

                ========================================== */



                else if (

                    data.claimStatusValue ===

                        'under_review' ||

                    data.claimStatusValue ===

                        'under review'

                ) {



                    data.claimStatusTitle =

                        'Ownership claim is under review';





                    data.claimStatusMessage =

                        'Your existing ownership claim is currently being reviewed. You do not need to submit another claim.';



                }





                /* ==========================================

                   WITHDRAWN

                ========================================== */



                else if (

                    data.claimStatusValue ===

                        'withdrawn'

                ) {



                    data.claimWithdrawn =

                        true;





                    data.claimStatusTitle =

                        'You withdrew this ownership claim';





                    data.claimStatusMessage =

                        'You withdrew your ownership claim for this match. This same match cannot be claimed again, but CampusMatch can continue looking for other eligible matches.';





                    /*
                     * A withdrawn Claim is closed.
                     * Do not send the user back into the
                     * ownership-verification page.
                     */

                    data.existingClaimUrl =

                        '';



                }





                /* ==========================================

                   CANCELLED

                ========================================== */



                else if (

                    data.claimStatusValue ===

                        'cancelled' ||

                    data.claimStatusValue ===

                        'canceled'

                ) {



                    data.claimStatusTitle =

                        'Ownership claim is closed';





                    data.claimStatusMessage =

                        'This ownership claim has been closed. You cannot start another claim for the same match.';





                    data.existingClaimUrl =

                        '';



                }





                /* ==========================================

                   SUBMITTED / OTHER ACTIVE STATE

                ========================================== */



                else {



                    data.claimStatusTitle =

                        'Ownership claim already submitted';





                    data.claimStatusMessage =

                        'You already have an ownership claim for this match. CampusMatch will continue using the existing claim.';



                }

            }

        }

    }





    /* ======================================================

       SCORES

    ====================================================== */



    var overall =

        readScore(

            match,

            F_OVERALL

        );





    var levelValue =

        (

            match.getValue(

                F_LEVEL

            ) || ''

        )

        .toString()

        .toLowerCase()

        .trim();





    var levelDisplay =

        match.getDisplayValue(

            F_LEVEL

        ) || '';





    if (!levelValue) {



        if (

            overall >= 80

        ) {



            levelValue =

                'strong';



            levelDisplay =

                'Strong';

        }

        else if (

            overall >= 65

        ) {



            levelValue =

                'potential';



            levelDisplay =

                'Potential';

        }

        else {



            levelValue =

                'low';



            levelDisplay =

                'Low';

        }

    }





    /* ======================================================

       MATCH STATUS

    ====================================================== */



    var statusValue =

        (

            match.getValue(

                F_STATUS

            ) || ''

        )

        .toString()

        .toLowerCase()

        .trim();





    var statusDisplay =

        match.getDisplayValue(

            F_STATUS

        ) || 'Active';





    /* ======================================================

       DECISION REASON

       SIMPLE SERVICENOW-SAFE VERSION

    ====================================================== */



    var decisionReasonValue =

        '';



    var decisionReasonDisplay =

        '';



    if (

        match.isValidField(

            'decision_reason'

        )

    ) {



        decisionReasonValue =

            match.getValue(

                'decision_reason'

            ) || '';



        decisionReasonDisplay =

            match.getDisplayValue(

                'decision_reason'

            ) || '';

    }





    decisionReasonValue =

        decisionReasonValue

        .toString()

        .toLowerCase()

        .trim();





    data.matchWithdrawn =

        statusValue ===

            'withdrawn';





    /* ======================================================

       BUILD SAFE MATCH RESPONSE

    ====================================================== */



    data.match = {



        sys_id:

            match.getUniqueValue(),



        overallScore:

            overall,



        levelValue:

            levelValue,



        levelDisplay:

            levelDisplay,



        statusValue:

            statusValue,



        statusDisplay:

            statusDisplay,



        decisionReasonValue:

            decisionReasonValue,



        decisionReasonDisplay:

            decisionReasonDisplay,



        lost: {



            title:

                lost.getValue(

                    'title'

                ) ||

                'Lost Item',



            category:

                lost.getDisplayValue(

                    'category'

                ) ||

                '—',



            location:

                lost.getDisplayValue(

                    'location_zone'

                ) ||

                'Campus',



            reported:

                lost.getDisplayValue(

                    'reported_date_time'

                ) ||

                '—'

        },



        found: {



            /*
             * Keep Found item privacy-safe.
             */

            title:

                found.getDisplayValue(

                    'public_title'

                ) ||

                'Found Item',



            category:

                found.getDisplayValue(

                    'category'

                ) ||

                '—',



            location:

                found.getDisplayValue(

                    'location_zone'

                ) ||

                'Campus',



            reported:

                found.getDisplayValue(

                    'reported_date_time'

                ) ||

                '—'

        },



        factors: [



            {

                label:

                    'Image Attributes',



                score:

                    readScore(

                        match,

                        F_IMAGE

                    ),



                weight:

                    35

            },



            {

                label:

                    'Description Similarity',



                score:

                    readScore(

                        match,

                        F_DESCRIPTION

                    ),



                weight:

                    20

            },



            {

                label:

                    'Location',



                score:

                    readScore(

                        match,

                        F_LOCATION

                    ),



                weight:

                    15

            },



            {

                label:

                    'Time',



                score:

                    readScore(

                        match,

                        F_TIME

                    ),



                weight:

                    10

            },



            {

                label:

                    'Category',



                score:

                    readScore(

                        match,

                        F_CATEGORY

                    ),



                weight:

                    10

            },



            {

                label:

                    'Unique Attributes',



                score:

                    readScore(

                        match,

                        F_UNIQUE

                    ),



                weight:

                    10

            }

        ]

    };





    /* ======================================================

       MULTIPLE STRONG MATCH CHECK

    ====================================================== */



    var strongCandidateCount =

        0;





    var ambiguityCheck =

        new GlideRecord(

            MATCH_TABLE

        );





    ambiguityCheck.addQuery(

        'found_item',

        foundId

    );





    ambiguityCheck.addQuery(

        'overall_score',

        '>=',

        80

    );





    ambiguityCheck.query();





    while (

        ambiguityCheck.next()

    ) {



        var ambiguityStatus =

            (

                ambiguityCheck.getValue(

                    'status'

                ) || ''

            )

            .toString()

            .toLowerCase()

            .trim();





        if (

            ambiguityStatus ===

                'no_match' ||

            ambiguityStatus ===

                'rejected' ||

            ambiguityStatus ===

                'confirmed' ||

            ambiguityStatus ===

                'resolved' ||

            ambiguityStatus ===

                'withdrawn'

        ) {



            continue;

        }





        strongCandidateCount++;

    }





    data.disambiguationRequired =

        strongCandidateCount > 1;





    /* ======================================================

       REJECTED MATCH?

    ====================================================== */



    data.matchRejected =

        (

            statusValue ===

                'no_match' ||

            statusValue ===

                'rejected'

        );





    /* ======================================================

       POTENTIAL MATCH STAFF REVIEW CHECK

    ====================================================== */



    var isPotential =

        levelValue ===

            'potential';





    var hasReviewAudit =

        false;





    if (

        match.isValidField(

            'reviewed_by'

        ) &&

        match.getValue(

            'reviewed_by'

        )

    ) {



        hasReviewAudit =

            true;

    }





    if (

        match.isValidField(

            'reviewed_on'

        ) &&

        match.getValue(

            'reviewed_on'

        )

    ) {



        hasReviewAudit =

            true;

    }





    var potentialMatchVerified =

        isPotential &&

        (

            statusValue ===

                'confirmed' ||

            (

                statusValue ===

                    'active' &&

                hasReviewAudit

            )

        );





    /*
     * Potential Match:
     * student must wait until staff verifies it.
     */

    data.staffReviewRequired =

        data.ownsLost &&

        isPotential &&

        !potentialMatchVerified &&

        !data.matchRejected &&

        !data.matchWithdrawn;





    /* ======================================================

       CLAIM PERMISSION

       FINAL RULE:

       User may start ownership verification ONLY IF:

       1. They own the Lost report.
       2. NO previous Claim exists for this Match.
       3. Score is at least 65.
       4. Strong OR staff-approved Potential.
       5. No multiple-strong disambiguation is pending.
       6. Match itself has not been rejected.
       7. Match has not been withdrawn.

    ====================================================== */



    var levelAllowsVerification =

        (

            levelValue ===

                'strong'

        ) ||

        (

            levelValue ===

                'potential' &&

            potentialMatchVerified

        );





    /* ======================================================

       NOT MY ITEM PERMISSION

    ====================================================== */



    data.canDismissMatch =

        data.ownsLost &&

        !data.hasExistingClaim &&

        !data.matchRejected &&

        !data.matchWithdrawn &&

        statusValue !== 'resolved';





    data.canClaim =

        data.ownsLost &&

        !data.hasExistingClaim &&

        overall >= 65 &&

        levelAllowsVerification &&

        !data.disambiguationRequired &&

        !data.matchRejected &&

        !data.matchWithdrawn;



})();
